 cases.push(test('Draft CAS explicit Load replaces local buffers with the saved drafts',async()=>{input('workspace-notes','discarded local draft');drafts.revision++;drafts.drafts.workspace_notes='saved edits to load';stamp();await assert.rejects(w.StudioDrafts.flush(),/revision|conflict|saved drafts/i);click(named('Load saved edits'));await until(()=>!d.querySelector('dialog[open]'),'load draft conflict');assert.equal($('workspace-notes').value,'saved edits to load');}));
 cases.push(test('Project Open quiesces graph autosave before commit and ignores old delayed work while draft loading waits',async()=>{await view('nodes');d.body.dispatchEvent(new w.KeyboardEvent('keydown',{key:'Escape',bubbles:true}));input('graph-name','OLD unsaved graph name');let release;delayedDrafts=new Promise(r=>release=r);Object.defineProperty($('project-file'),'files',{configurable:true,value:[{text:async()=>'{"raw":"import"}'}]});$('project-file').dispatchEvent(new w.Event('change'));await settle();const dialog=d.querySelector('dialog[open]');assert(dialog);submit(dialog.querySelector('form'));await until(()=>projectCommits===1,'project commit');await wait(725);assert.equal(graphs.graphs[0].name,'Imported project graph');assert(!calls.some(c=>c.projectCommits===1&&c.method==='POST'&&c.path==='/api/graph/action'&&M.parseTransportJSON(c.body).action==='graph.update'&&M.parseTransportJSON(c.body).graph.name==='OLD unsaved graph name'));release();await until(()=>graphDraft()?.name==='Imported project graph','post-import reload');assert.equal(w.StudioBridge.getEpoch(),epoch);}));
 cases.push(test('Cross-tab project replacement blocks stale mutations and downloads, retains local recovery and explicitly reloads',async()=>{await view('journal');input('workspace-notes','retained old-tab notebook');const captured=w.StudioBridge.getEpoch();epoch='offline-other-tab-replacement';stamp();await w.StudioBridge.refresh();assert.equal(w.StudioBridge.getEpoch(),captured);assert(w.StudioBridge.isWorkspaceReplaced());assert.equal($('workspace-notes').value,'retained old-tab notebook');click(named('Download this tab’s drafts'));const recovery=await downloads.at(-1).blob.text();assert(recovery.includes('retained old-tab notebook'));click(named('Reload saved project'));await until(()=>!w.StudioBridge.isWorkspaceReplaced(),'explicit replacement reload');await until(()=>!d.querySelector('dialog[open]'),'replacement dialog close');assert.equal(w.StudioBridge.getEpoch(),epoch);}));
